function uid() {
  return (crypto.randomUUID ? crypto.randomUUID() : Date.now() + "-" + Math.random().toString(16).slice(2));
}
function money(n) {
  // Always to the cent: $5,720.00, $1,234.56
  return "$" + (Math.round((Number(n) || 0) * 100) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function fmtDate(d) {
  if (!d) return "—";
  return new Date(d).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}
// Calendar-date helpers for date inputs ("YYYY-MM-DD" in local time)
function todayInput() { return new Date().toLocaleDateString("en-CA"); }
function toDateInput(v) {
  if (!v) return "";
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const d = new Date(v);
  return isNaN(d) ? "" : d.toLocaleDateString("en-CA");
}
function fromDateInput(v) { return v ? `${v}T12:00:00` : null; }
const STAGE_FOR_STATUS = { pending_auth1: "auth1", pending_auth2: "auth2", pending_chief: "chief" };
const PAPER_STAGES = [["auth1", "Purchaser's signature"], ["auth2", "Pre-approval"], ["chief", "Final approval"]];
const STAGE_ROLE = { auth1: "approver1", auth2: "approver2", chief: "fire_chief" };
const NEXT_STAGE = { auth1: "auth2", auth2: "chief", chief: null };

// Someone's home division, plus any they're set to sign for
function coversDivision(u, division) {
  return !!u && (u.division === division || (u.signDivisions || []).includes(division));
}
// People who sign a stage for a division (master admins can too, but aren't listed)
function signersFor(roster, stage, division) {
  if (!stage) return [];
  return roster
    .filter(u => u.role === STAGE_ROLE[stage] && (stage === "chief" || coversDivision(u, division)))
    .sort((a, b) => a.name.localeCompare(b.name));
}
function canSignStage(me, req) {
  const stage = STAGE_FOR_STATUS[req.status];
  if (!me || !stage) return null;
  if (me.role === "master") return stage;
  if (me.role !== STAGE_ROLE[stage]) return null;
  return stage === "chief" || coversDivision(me, req.division) ? stage : null;
}
function canMarkReqPaid(me, req) {
  if (!me || req.status !== "approved") return false;
  return ["master", "fire_chief", "accounting"].includes(me.role) || (me.role === "approver2" && coversDivision(me, req.division));
}
// Waiting on this person: sent to them, or not sent to anyone and theirs to sign.
// (Master admins can sign anything, so only what's sent to them counts.)
function isWaitingOnMe(me, req) {
  if (!canSignStage(me, req)) return false;
  if (req.nextSignerId) return req.nextSignerId === me.id;
  return me.role !== "master";
}
function waitingSummary(me, reqs) {
  const out = { auth1: 0, auth2: 0, chief: 0, paid: 0, sentToMe: 0, total: 0 };
  if (!me) return out;
  for (const r of reqs) {
    if (isWaitingOnMe(me, r)) {
      out[STAGE_FOR_STATUS[r.status]]++;
      out.total++;
      if (r.nextSignerId === me.id) out.sentToMe++;
    }
    if (["master", "accounting"].includes(me.role) && canMarkReqPaid(me, r)) out.paid++;
  }
  return out;
}

function annualized(req) {
  const mult = FREQ[req.frequency]?.mult || 0;
  return req.amount * mult;
}
function reqAmount(req) {
  return (req.lineItems && req.lineItems.length > 0) ? req.lineItems.reduce((s, li) => s + (li.amount || 0), 0) : (req.amount || 0);
}
function reqTotals(req) {
  if (req.lineItems && req.lineItems.length > 0) {
    let recurring = 0, oneTime = 0;
    req.lineItems.forEach(li => {
      const amt = li.amount || 0;
      const mult = FREQ[li.frequency]?.mult || 0;
      if (li.frequency === "one_time") oneTime += amt;
      else recurring += amt * mult;
    });
    return { recurring, oneTime };
  }
  return { recurring: annualized(req), oneTime: req.frequency === "one_time" ? (req.amount || 0) : 0 };
}
function reimbLineTotal(item, type, mileageRate) {
  if (type === "travel") {
    const mileagePerDiem = (parseFloat(item.miles) || 0) * mileageRate;
    return (parseFloat(item.lodging) || 0) + mileagePerDiem + (parseFloat(item.mealsPerDiem) || 0) + (parseFloat(item.parking) || 0) + (parseFloat(item.other) || 0);
  }
  return (parseFloat(item.qty) || 0) * (parseFloat(item.unitPrice) || 0);
}
function reimbSubtotal(req, mileageRate) {
  return (req.lineItems || []).reduce((s, li) => s + reimbLineTotal(li, req.type, mileageRate), 0);
}
function reimbTotal(req, mileageRate) {
  const subtotal = reimbSubtotal(req, mileageRate);
  return req.type === "travel" ? subtotal - (parseFloat(req.advances) || 0) : subtotal;
}
function normalizeFrequency(raw) {
  const s = (raw || "").trim().toLowerCase();
  if (["", "one_time", "one-time", "onetime", "one time"].includes(s)) return "one_time";
  if (["monthly", "month"].includes(s)) return "monthly";
  if (["quarterly", "quarter"].includes(s)) return "quarterly";
  if (["semiannually", "semi-annually", "semi annually", "semiannual", "semi-annual", "biannual", "biannually"].includes(s)) return "semiannually";
  if (["yearly", "annual", "annually", "year"].includes(s)) return "yearly";
  return null;
}
function getField(row, ...names) {
  const keys = Object.keys(row);
  for (const key of keys) {
    if (names.some(n => n.toLowerCase() === key.trim().toLowerCase())) return (row[key] || "").toString();
  }
  return "";
}

function escapeHtml(str) {
  return String(str ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function printDocument(title, bodyHtml) {
  const html = `<!DOCTYPE html><html><head><title>${escapeHtml(title)}</title><style>
    body { font-family: Georgia, 'Times New Roman', serif; color: #1C2634; padding: 32px; max-width: 800px; margin: 0 auto; }
    h1 { font-size: 19px; margin: 4px 0 2px; }
    h2 { font-size: 14px; margin: 22px 0 8px; border-bottom: 1px solid #999; padding-bottom: 4px; }
    table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 14px; }
    th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #ddd; vertical-align: top; }
    th { border-bottom: 2px solid #333; font-weight: bold; }
    .meta { font-size: 12px; color: #555; margin: 1px 0; }
    .label { font-weight: bold; white-space: nowrap; }
    .total { font-weight: bold; }
    @media print { body { padding: 0.4in; } }
  </style></head><body>${bodyHtml}</body></html>`;

  let iframe = document.getElementById("print-frame");
  if (!iframe) {
    iframe = document.createElement("iframe");
    iframe.id = "print-frame";
    iframe.style.position = "fixed";
    iframe.style.right = "0";
    iframe.style.bottom = "0";
    iframe.style.width = "0";
    iframe.style.height = "0";
    iframe.style.border = "0";
    document.body.appendChild(iframe);
  }
  const doc = iframe.contentWindow.document;
  doc.open();
  doc.write(html);
  doc.close();
  setTimeout(() => {
    try {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
    } catch (e) {}
  }, 300);
  return true;
}

function letterhead(subtitle) {
  return `<div style="display:flex; align-items:center; gap:12px; margin-bottom:18px;">
    <img src="${LOGO_DATA_URL}" style="width:48px; height:48px;" />
    <div>
      <div style="font-size:16px; font-weight:bold;">${escapeHtml(BRAND.org)}</div>
      <div style="font-size:12.5px; color:#555;">${escapeHtml(subtitle)}</div>
    </div>
  </div>`;
}

function printRequisition(r) {
  const sigImg = (stage, rec) => rec.signature || (rec.drawn ? `${window.location.origin}/api/req-signature/${r.id}/${stage}` : "");
  const sigRow = (label, rec, stage) => {
    if (rec) {
      const img = sigImg(stage, rec);
      return `<tr><td class="label" style="width:170px;">${label}</td><td>${escapeHtml(rec.name)}${img ? `<br><img src="${img}" alt="Signature" style="height:44px;max-width:220px;">` : ""}</td><td>${fmtDate(rec.date)}</td></tr>`;
    }
    return `<tr><td class="label" style="width:170px;">${label}</td><td colspan="2">
      <span style="display:inline-block; border-top:1px solid #333; width:220px;">&nbsp;</span>
      &nbsp;&nbsp;Date:&nbsp;<span style="display:inline-block; border-top:1px solid #333; width:100px;">&nbsp;</span>
    </td></tr>`;
  };
  const itemsHtml = (r.lineItems && r.lineItems.length > 0)
    ? `<table><thead><tr><th>Description</th><th>Frequency</th><th style="text-align:right">Amount</th></tr></thead><tbody>
        ${r.lineItems.map(li => `<tr><td>${escapeHtml(li.description)}</td><td>${FREQ[li.frequency].label}</td><td style="text-align:right">${money(li.amount)}</td></tr>`).join("")}
        <tr><td colspan="2" class="total">Total</td><td class="total" style="text-align:right">${money(reqAmount(r))}</td></tr>
      </tbody></table>`
    : `<p><span class="label">Amount:</span> ${money(reqAmount(r))} (${FREQ[r.frequency].label})</p>`;

  const body = `
    ${letterhead("Purchase requisition")}
    <h1>${escapeHtml(r.title)}</h1>
    <div class="meta">Requisition ID: ${r.id}</div>
    <div class="meta">Submitted ${fmtDate(r.createdAt)} by ${escapeHtml(r.requestedBy)}</div>
    <div class="meta">Status: ${STAGE_LABEL[r.status]}</div>

    <h2>Details</h2>
    <table>
      <tr><td class="label" style="width:160px;">Division</td><td>${escapeHtml(r.division)}</td></tr>
      <tr><td class="label">Category</td><td>${escapeHtml(r.category)}</td></tr>
      <tr><td class="label">Vendor</td><td>${escapeHtml(r.vendor)}</td></tr>
      <tr><td class="label">Contractual</td><td>${r.contractual ? "Yes" : "No"}</td></tr>
      <tr><td class="label">Invoice #</td><td>${escapeHtml(r.invoiceNumber || "—")}</td></tr>
      <tr><td class="label">Payment method</td><td>${escapeHtml(r.paymentMethod || "—")}${r.paymentMethod === "Credit card" && r.cardLast4 ? ` (card ending ${escapeHtml(r.cardLast4)}, ${escapeHtml(r.cardholderName)})` : ""}</td></tr>
    </table>

    ${r.description ? `<h2>Description / justification</h2><p style="font-size:13px;">${escapeHtml(r.description)}</p>` : ""}

    <h2>Amount</h2>
    ${itemsHtml}

    <h2>Signatures</h2>
    <table>
      ${sigRow("Purchaser's signature", r.auth1, "auth1")}
      ${sigRow("Pre-approval", r.auth2, "auth2")}
      ${sigRow("Final approval", r.chief, "chief")}
    </table>
    ${r.status === "rejected" ? `<p style="color:#9A3324; font-size:13px;"><span class="label">Rejected:</span> ${escapeHtml(r.rejectedReason)}</p>` : ""}
    ${r.status === "paid" ? `<p style="font-size:13px;"><span class="label">Paid:</span> ${fmtDate(r.paidDate)}</p>` : ""}
    ${(r.attachments && r.attachments.length > 0) ? `<h2>Attached documents</h2><ul style="font-size:13px;">${r.attachments.map(a => `<li>${escapeHtml(a.name)}</li>`).join("")}</ul>` : ""}
  `;
  printDocument(`Requisition — ${r.title}`, body);
}

